// Temporary benchmark harness: measures OrcaWorkspaceAdapter::export_project_archive
// (the Agent timeline "restorable copy") against generated high-resolution meshes,
// plus Model copy cost. Not part of the tree; built via a temporary CMake target.
#include "libslic3r/Format/bbs_3mf.hpp"
#include "libslic3r/Model.hpp"
#include "libslic3r/PresetBundle.hpp"
#include "libslic3r/Thread.hpp"
#include "libslic3r/TriangleMesh.hpp"
#include "libslic3r/Utils.hpp"
#include "libslic3r/libslic3r.h"
#include "slic3r/GUI/GLCanvas3D.hpp"
#include "slic3r/GUI/GUI_App.hpp"
#include "slic3r/GUI/GUI_Init.hpp"
#include "slic3r/GUI/JusPrin/Workspace/OrcaWorkspaceAdapter.hpp"
#include "slic3r/GUI/MainFrame.hpp"
#include "slic3r/GUI/PartPlate.hpp"
#include "slic3r/GUI/Plater.hpp"

#include <wx/app.h>

#include <boost/filesystem.hpp>

#include <atomic>
#include <chrono>
#include <cmath>
#include <functional>
#include <iostream>
#include <memory>
#include <string>
#include <thread>
#include <vector>

namespace fs = boost::filesystem;

namespace Slic3r::GUI::JusPrin::Workspace {
namespace {

struct HarnessState
{
    std::atomic<int>  result{-1};
    std::atomic<bool> stop{false};
    std::shared_ptr<void> runner;
    std::chrono::steady_clock::time_point deadline{std::chrono::steady_clock::now() + std::chrono::seconds(1800)};
    fs::path scratch;
    std::vector<std::size_t> triangle_targets;
};

using Clock = std::chrono::steady_clock;
double ms_since(Clock::time_point start)
{
    return std::chrono::duration<double, std::milli>(Clock::now() - start).count();
}

class Scenario final : public std::enable_shared_from_this<Scenario>
{
public:
    Scenario(GUI_App& app, std::shared_ptr<HarnessState> state) : m_app(app), m_state(std::move(state)) {}

    void start()
    {
        m_plater = m_app.plater();
        wait_until([this] {
            GLCanvas3D* canvas = m_plater->get_view3D_canvas3D();
            return canvas != nullptr && canvas->is_initialized();
        }, [self = shared_from_this()] { self->run_next_size(); });
    }

private:
    void wait_until(std::function<bool()> condition, std::function<void()> then)
    {
        if (m_state->stop)
            return;
        if (Clock::now() >= m_state->deadline) {
            fail("timeout while waiting");
            return;
        }
        if (condition()) {
            then();
            return;
        }
        m_app.CallAfter([self = shared_from_this(), condition, then] { self->wait_until(condition, then); });
    }

    // Let the event loop drain N times before continuing.
    void settle(int turns, std::function<void()> then)
    {
        if (turns <= 0) {
            then();
            return;
        }
        m_app.CallAfter([self = shared_from_this(), turns, then] { self->settle(turns - 1, then); });
    }

    void run_next_size()
    {
        try {
            if (m_index >= m_state->triangle_targets.size()) {
                finish();
                return;
            }
            const std::size_t target = m_state->triangle_targets[m_index++];
            bench_size(target);
        } catch (const std::exception& error) {
            fail(std::string("exception: ") + error.what());
        } catch (...) {
            fail("unknown exception");
        }
    }

    void bench_size(std::size_t target_triangles)
    {
        if (m_plater->new_project(true, true) == wxID_CANCEL) {
            fail("new_project cancelled");
            return;
        }
        // Sphere triangle count is ~ 4*pi^2 / fa^2, so fa = 2*pi / sqrt(N).
        const double fa = 2.0 * M_PI / std::sqrt(double(target_triangles));
        indexed_triangle_set its = its_make_sphere(50.0, fa);
        const std::size_t triangles = its.indices.size();
        const std::size_t vertices  = its.vertices.size();
        const std::size_t its_bytes = triangles * sizeof(stl_triangle_vertex_indices) + vertices * sizeof(stl_vertex);
        const fs::path stl = m_state->scratch / ("sphere-" + std::to_string(triangles) + ".stl");
        if (!its_write_stl_binary(stl.string().c_str(), "sphere", its)) {
            fail("stl write failed");
            return;
        }
        boost::system::error_code ec;
        const auto stl_bytes = fs::file_size(stl, ec);
        std::cerr << "BENCH MESH triangles=" << triangles << " vertices=" << vertices << " its_bytes=" << its_bytes
                  << " stl_bytes=" << stl_bytes << '\n';

        const auto load_start = Clock::now();
        const std::vector<size_t> loaded = m_plater->load_files(
            std::vector<std::string>{stl.string()},
            LoadStrategy::LoadModel | LoadStrategy::AddDefaultInstances | LoadStrategy::Silence, false);
        const double load_ms = ms_since(load_start);
        if (loaded.size() != 1) {
            fail("load failed");
            return;
        }
        PartPlateList& plates = m_plater->get_partplate_list();
        plates.get_plate(0)->add_instance(0, 0, true);
        m_plater->canvas3D()->reload_scene(true, true);
        std::cerr << "BENCH LOAD triangles=" << triangles << " load_ms=" << load_ms
                  << " model_objects=" << m_plater->model().objects.size() << '\n';

        settle(5, [self = shared_from_this(), triangles, stl_bytes] { self->measure(triangles, stl_bytes); });
    }

    void measure(std::size_t triangles, std::uintmax_t stl_bytes)
    {
        OrcaWorkspaceAdapter workspace(*m_plater);
        boost::system::error_code ec;
        for (int run = 0; run < 3; ++run) {
            const fs::path out = m_state->scratch / ("export-" + std::to_string(triangles) + "-" + std::to_string(run) + ".3mf");
            const auto start = Clock::now();
            const CommandResult result = workspace.export_project_archive(out.string());
            const double ms = ms_since(start);
            const auto bytes = result.succeeded() ? fs::file_size(out, ec) : 0;
            std::cerr << "BENCH EXPORT triangles=" << triangles << " stl_bytes=" << stl_bytes << " run=" << run
                      << " ok=" << result.succeeded() << " export_ms=" << ms << " file_bytes=" << bytes
                      << " main_thread=" << wxIsMainThread() << '\n';
        }

        // Serialization only (no GL thumbnails): what a worker thread would have to do.
        {
            PresetBundle& bundle = *m_app.preset_bundle;
            DynamicPrintConfig cfg = bundle.full_config_secure();
            for (int run = 0; run < 3; ++run) {
                PlateDataPtrs plate_data_list;
                m_plater->get_partplate_list().store_to_3mf_structure(plate_data_list, false, -1);
                std::vector<Preset*> project_presets = bundle.get_current_project_embedded_presets();
                const fs::path out = m_state->scratch / ("store-only-" + std::to_string(triangles) + "-" + std::to_string(run) + ".3mf");
                const std::string path_u8 = out.string();
                StoreParams sp;
                sp.path            = path_u8.c_str();
                sp.model           = &m_plater->model();
                sp.plate_data_list = plate_data_list;
                sp.project_presets = project_presets;
                sp.config          = &cfg;
                sp.strategy        = SaveStrategy::Silence | SaveStrategy::SplitModel | SaveStrategy::ShareMesh |
                              SaveStrategy::SkipAuxiliary | SaveStrategy::Zip64;
                const auto start = Clock::now();
                const bool ok = store_bbs_3mf(sp);
                const double ms = ms_since(start);
                std::cerr << "BENCH STORE_ONLY triangles=" << triangles << " run=" << run << " ok=" << ok
                          << " store_ms=" << ms << " file_bytes=" << (ok ? fs::file_size(out, ec) : 0) << '\n';
                release_PlateData_list(plate_data_list);
            }
        }

        // Model copy cost: shallow (shared_ptr mesh) vs deep TriangleMesh copy.
        for (int run = 0; run < 3; ++run) {
            const auto start = Clock::now();
            Model copy(m_plater->model());
            const double ms = ms_since(start);
            const ModelVolume* src = m_plater->model().objects.front()->volumes.front();
            const ModelVolume* dst = copy.objects.front()->volumes.front();
            std::cerr << "BENCH MODEL_COPY triangles=" << triangles << " run=" << run << " copy_ms=" << ms
                      << " mesh_ptr_shared=" << (src->mesh_ptr().get() == dst->mesh_ptr().get())
                      << " use_count=" << src->mesh_ptr().use_count() << '\n';
        }
        for (int run = 0; run < 3; ++run) {
            const ModelVolume* src = m_plater->model().objects.front()->volumes.front();
            const auto start = Clock::now();
            TriangleMesh deep(src->mesh());
            const double ms = ms_since(start);
            std::cerr << "BENCH MESH_DEEP_COPY triangles=" << triangles << " run=" << run << " copy_ms=" << ms
                      << " facets=" << deep.facets_count() << '\n';
        }

        // Worker-thread store from a Model copy (hypothesis probe): serialize the
        // shared-mesh copy on a std::thread while the UI thread waits.
        {
            PresetBundle& bundle = *m_app.preset_bundle;
            DynamicPrintConfig cfg = bundle.full_config_secure();
            PlateDataPtrs plate_data_list;
            m_plater->get_partplate_list().store_to_3mf_structure(plate_data_list, false, -1);
            std::vector<Preset*> project_presets = bundle.get_current_project_embedded_presets();
            const fs::path out = m_state->scratch / ("worker-" + std::to_string(triangles) + ".3mf");
            const std::string path_u8 = out.string();
            const auto copy_start = Clock::now();
            Model copy(m_plater->model());
            const double copy_ms = ms_since(copy_start);
            double worker_ms = 0;
            bool ok = false;
            std::thread worker([&] {
                StoreParams sp;
                sp.path            = path_u8.c_str();
                sp.model           = &copy;
                sp.plate_data_list = plate_data_list;
                sp.project_presets = project_presets;
                sp.config          = &cfg;
                sp.strategy        = SaveStrategy::Silence | SaveStrategy::SplitModel | SaveStrategy::ShareMesh |
                              SaveStrategy::SkipAuxiliary | SaveStrategy::Zip64;
                const auto start = Clock::now();
                ok = store_bbs_3mf(sp);
                worker_ms = ms_since(start);
            });
            worker.join();
            std::cerr << "BENCH WORKER_STORE triangles=" << triangles << " copy_ms=" << copy_ms << " ok=" << ok
                      << " worker_store_ms=" << worker_ms << " file_bytes=" << (ok ? fs::file_size(out, ec) : 0) << '\n';
            release_PlateData_list(plate_data_list);
        }

        settle(2, [self = shared_from_this()] { self->run_next_size(); });
    }

    void fail(const std::string& message)
    {
        std::cerr << "HARNESS ERROR " << message << '\n';
        ++m_failures;
        finish();
    }

    void finish()
    {
        if (m_finished)
            return;
        m_finished = true;
        std::cerr << "HARNESS RESULT " << (m_failures == 0 ? "PASS" : "FAIL") << '\n';
        m_state->result = m_failures == 0 ? 0 : 1;
        m_state->stop = true;
        m_app.ExitMainLoop();
    }

    GUI_App&                      m_app;
    std::shared_ptr<HarnessState> m_state;
    Plater*                       m_plater{nullptr};
    std::size_t                   m_index{0};
    int                           m_failures{0};
    bool                          m_finished{false};
};

void start_when_ready(GUI_App& app, const std::shared_ptr<HarnessState>& state)
{
    if (state->stop)
        return;
    if (Clock::now() >= state->deadline) {
        std::cerr << "HARNESS ERROR application did not become ready before timeout\n";
        state->result = 1;
        state->stop = true;
        app.ExitMainLoop();
        return;
    }
    if (app.mainframe != nullptr && app.plater() != nullptr) {
        auto scenario = std::make_shared<Scenario>(app, state);
        state->runner = scenario;
        scenario->start();
        return;
    }
    app.CallAfter([&app, state] { start_when_ready(app, state); });
}

} // namespace
} // namespace Slic3r::GUI::JusPrin::Workspace

int main(int argc, char** argv)
{
    using namespace Slic3r;
    using namespace Slic3r::GUI;
    using namespace Slic3r::GUI::JusPrin::Workspace;

    const fs::path original_directory = fs::current_path();
    const fs::path data_directory = fs::temp_directory_path() / fs::unique_path("jusprin-exportbench-%%%%-%%%%");
    fs::create_directories(data_directory / "log");
    fs::copy_file(fs::path(JUSPRIN_SOURCE_DIR) / "tests/data/jusprin/harness.conf",
                  data_directory / (std::string(SLIC3R_APP_KEY) + ".conf"), fs::copy_option::overwrite_if_exists);

    const fs::path resources = fs::path(JUSPRIN_SOURCE_DIR) / "resources";
    set_resources_dir(resources.string());
    set_var_dir((resources / "images").string());
    set_local_dir((resources / "i18n").string());
    set_sys_shapes_dir((resources / "shapes").string());
    set_custom_gcodes_dir((resources / "custom_gcodes").string());
    set_data_dir(data_directory.string());
    set_temporary_dir(data_directory.string());
    save_main_thread_id();

    auto state = std::make_shared<HarnessState>();
    state->scratch = fs::path(BENCH_SCRATCH_DIR);
    fs::create_directories(state->scratch);
    std::vector<char*> gui_arguments;
    gui_arguments.emplace_back(argv[0]);
    for (int index = 1; index < argc; ++index) {
        const std::string argument(argv[index]);
        if (argument.rfind("--triangles=", 0) == 0)
            state->triangle_targets.emplace_back(std::stoul(argument.substr(12)));
        else
            gui_arguments.emplace_back(argv[index]);
    }
    if (state->triangle_targets.empty())
        state->triangle_targets = {100000, 400000, 1000000};

    std::thread installer([state] {
        while (!state->stop && std::chrono::steady_clock::now() < state->deadline) {
            if (auto* app = dynamic_cast<GUI_App*>(wxApp::GetInstance())) {
                app->CallAfter([app, state] { start_when_ready(*app, state); });
                return;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
        state->result = 1;
        state->stop = true;
    });

    GUI_InitParams params;
    params.argc = static_cast<int>(gui_arguments.size());
    params.argv = gui_arguments.data();
    const int gui_result = GUI_Run(params);
    state->stop = true;
    installer.join();

    fs::current_path(original_directory);
    fs::remove_all(data_directory);
    if (state->result < 0)
        return gui_result == 0 ? 1 : gui_result;
    return state->result;
}

